def compute(vars):
    assets = vars["v1"]
    liabilities = vars["v2"]
    net_trading_assets = assets - liabilities

    return {
        "value": net_trading_assets,
        "trace": {
            "trading_assets": assets,
            "trading_liabilities": liabilities,
            "net_trading_assets": net_trading_assets,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
